export function shouldCaptureCodexDump(bodyJson: string, flagText = ""): boolean {
	let parsed: { model?: unknown; tools?: unknown };
	try {
		parsed = JSON.parse(bodyJson) as { model?: unknown; tools?: unknown };
	} catch {
		return false;
	}

	const trimmed = flagText.trim();
	let filter: { marker?: unknown; model?: unknown; requireTools?: unknown } = { requireTools: true };
	if (trimmed.length > 0) {
		try {
			filter = { requireTools: true, ...(JSON.parse(trimmed) as object) };
		} catch {
			filter = { marker: trimmed, requireTools: true };
		}
	}

	if (filter.marker && !bodyJson.includes(String(filter.marker))) return false;
	if (filter.model && !String(parsed.model || "").includes(String(filter.model))) return false;
	if (filter.requireTools !== false && (!Array.isArray(parsed.tools) || parsed.tools.length === 0)) return false;
	return true;
}

function maybeDumpCodexRequest(bodyJson: string): void {
	try {
		if (!existsSync(CODEX_DUMP_FLAG)) return;
		const flagText = readFileSync(CODEX_DUMP_FLAG, "utf8");
		if (!shouldCaptureCodexDump(bodyJson, flagText)) return;
		if (CODEX_DUMP_ALL) {
			writeFileSync(`${CODEX_DUMP_OUTPUT}.${codexDumpSeq++}`, bodyJson);
			return; // stay armed to capture the whole turn
		}
		writeFileSync(CODEX_DUMP_OUTPUT, bodyJson);
		unlinkSync(CODEX_DUMP_FLAG);
	} catch {
		// audit hook must never affect request flow
	}
}

export function getEffectiveCodexTransport(
	transport: Transport | undefined,
	config: Pick<CodexConversionConfig["openai"], "forceCachedWebSockets"> | undefined,
): Transport {
	const configuredTransport = transport ?? "auto";
	if (config?.forceCachedWebSockets === false) return configuredTransport;
	if (configuredTransport === "websocket") return "websocket-cached";
	return configuredTransport;
}

