import type { RouterRoute, RouterTier } from "./types.ts";

export const AUTO_ALIASES = new Map<string, RouterRoute>([
  ["auto", "pi-fork/auto"],
  ["pi-fork/auto", "pi-fork/auto"],
  ["claude-bridge/auto", "claude-bridge/auto"],
  ["openai-codex/auto", "openai-codex/auto"],
]);

export const PROVIDER_CANDIDATES: Record<string, Record<RouterTier, string[]>> = {
  "claude-bridge": {
    cheap: ["claude-haiku-4-5"],
    medium: ["claude-sonnet-4-6", "claude-sonnet-4-5"],
    frontier: ["claude-opus-4-8", "claude-opus-4-7", "claude-opus-4-6"],
  },
  "openai-codex": {
    cheap: ["gpt-5.4-mini", "gpt-5-mini"],
    medium: ["gpt-5.4", "gpt-5"],
    frontier: ["gpt-5.5", "gpt-5.4-pro", "gpt-5-pro"],
  },
};

export const TIER_THINKING: Record<RouterTier, "low" | "medium" | "high"> = {
  cheap: "low",
  medium: "medium",
  frontier: "high",
};

export function normalizeRoute(requestedModel: string | undefined): RouterRoute | undefined {
  if (!requestedModel) return undefined;
  return AUTO_ALIASES.get(requestedModel.trim());
}

const ROUTABLE_PROVIDERS = ["openai-codex", "claude-bridge"] as const;

function isRoutableProvider(provider: string | undefined): provider is (typeof ROUTABLE_PROVIDERS)[number] {
  return provider === "openai-codex" || provider === "claude-bridge";
}

export function allowedProviders(route: RouterRoute, currentProvider?: string, preferredProvider?: string): string[] {
  if (route === "claude-bridge/auto") return ["claude-bridge"];
  if (route === "openai-codex/auto") return ["openai-codex"];
  if (isRoutableProvider(currentProvider)) return [currentProvider];
  if (isRoutableProvider(preferredProvider)) return [preferredProvider];
  return [...ROUTABLE_PROVIDERS];
}
