      signal: controller.signal,
      body: JSON.stringify(requestBody(endpoint, prompt, semanticRouter)),
    });
    if (!response.ok) return undefined;
    const raw = await response.text();
    const payload = raw.trim() ? JSON.parse(raw) as unknown : undefined;
    const headerTier = tierFromUnknown(response.headers?.get("x-vsr-selected-model") ?? undefined);
    const tier = headerTier ?? extractTier(payload);
    if (!tier) return undefined;
    return {
      tier,
      confidence: extractConfidenceFromHeaders(response.headers) ?? extractConfidence(payload),
      reason: uniqueStrings(["semantic_router", `endpoint:${endpoint}`, ...extractReasonFromHeaders(response.headers), ...extractReason(payload)]),
    };
  } catch {
    return undefined;
  } finally {
    clearTimeout(timeout);
  }
}

export function normalizeSemanticRouterEndpoint(endpoint: string): string {
  const trimmed = endpoint.trim().replace(/\/+$/, "");
  if (trimmed.endsWith("/api/v1/eval") || trimmed.endsWith("/v1/chat/completions")) return trimmed;
  if (trimmed.endsWith("/api/v1")) return `${trimmed}/eval`;
  if (trimmed.endsWith("/v1")) return `${trimmed}/chat/completions`;
  return `${trimmed}/v1/chat/completions`;
}

export const normalizeEvalEndpoint = normalizeSemanticRouterEndpoint;

export function extractTier(payload: unknown): RouterTier | undefined {
  const direct = tierFromUnknown(payload);
  if (direct) return direct;
  return findTierInModelFields(payload);
}

function uniqueStrings(values: string[]): string[] {
  return [...new Set(values)];
}

function requestBody(endpoint: string, prompt: string, semanticRouter: NonNullable<RouterConfig["semanticRouter"]>): Record<string, unknown> {
  if (endpoint.endsWith("/api/v1/eval")) {
    return {
      messages: [{ role: "user", content: prompt }],
      evaluate_all_signals: true,
    };
  }
  return {
    model: semanticRouter.model ?? process.env.PI_LLM_ROUTER_SEMANTIC_MODEL ?? "auto",
    messages: [{ role: "user", content: prompt }],
    max_tokens: semanticRouter.maxTokens ?? (Number(process.env.PI_LLM_ROUTER_SEMANTIC_MAX_TOKENS) || 1),
    temperature: 0,
  };
}

function promptFromMetadata(metadata: RoutingMetadata | undefined): string {
  const prompt = metadata?.promptPreview?.trim();
  if (prompt) return prompt;
  return JSON.stringify({ source: metadata?.source, agentId: metadata?.agentId, promptLength: metadata?.promptLength, cliMessageCount: metadata?.cliMessageCount });
}

function tierFromUnknown(value: unknown): RouterTier | undefined {
  if (typeof value !== "string") return undefined;
  return VALID_TIERS.has(value as RouterTier) ? (value as RouterTier) : undefined;
}

function findTierInModelFields(value: unknown): RouterTier | undefined {
  if (!value || typeof value !== "object") return undefined;
  if (Array.isArray(value)) {
    for (const item of value) {
      const tier = findTierInModelFields(item);
      if (tier) return tier;
    }
    return undefined;
  }

  const record = value as Record<string, unknown>;
  for (const [key, nested] of Object.entries(record)) {
    if (MODEL_FIELD_NAMES.has(key)) {
      const tier = tierFromUnknown(nested);
      if (tier) return tier;
    }
  }
  for (const [key, nested] of Object.entries(record)) {
    if (ADVISORY_MODEL_LIST_FIELDS.has(key)) continue;
    const tier = findTierInModelFields(nested);
    if (tier) return tier;
  }
  return undefined;
}

function extractConfidenceFromHeaders(headers: FetchResponse["headers"]): number | undefined {
  const raw = headers?.get("x-vsr-selected-confidence");
  if (!raw) return undefined;
  const value = Number(raw);
  if (!Number.isFinite(value)) return undefined;
  return Math.max(0, Math.min(1, value));
}

function extractConfidence(payload: unknown): number | undefined {
  const value = findNumberField(payload, new Set(["confidence", "score", "similarity", "selected_score", "selectedScore"]));
  if (value === undefined) return undefined;
  return Math.max(0, Math.min(1, value));
}

function findNumberField(value: unknown, names: Set<string>): number | undefined {
  if (!value || typeof value !== "object") return undefined;
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = findNumberField(item, names);
      if (found !== undefined) return found;
    }
    return undefined;
  }
  for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
    if (names.has(key) && typeof nested === "number" && Number.isFinite(nested)) return nested;
  }
  for (const nested of Object.values(value as Record<string, unknown>)) {
    const found = findNumberField(nested, names);
    if (found !== undefined) return found;
  }
  return undefined;
}

function extractReasonFromHeaders(headers: FetchResponse["headers"]): string[] {
  const decision = headers?.get("x-vsr-selected-decision");
  const model = headers?.get("x-vsr-selected-model");
  return [decision ? `decision:${decision}` : undefined, model ? `model:${model}` : undefined].filter((item): item is string => Boolean(item));
}

function extractReason(payload: unknown): string[] {
  if (!payload || typeof payload !== "object") return [];
  const record = payload as Record<string, unknown>;
  const decisionName = findStringField(record, new Set(["decision_name", "decisionName", "decision"]));
  const model = findModelName(record);
  return [decisionName ? `decision:${decisionName}` : undefined, model ? `model:${model}` : undefined].filter((item): item is string => Boolean(item));
}

function findStringField(value: unknown, names: Set<string>): string | undefined {
  if (!value || typeof value !== "object") return undefined;
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = findStringField(item, names);
      if (found) return found;
    }
    return undefined;
  }
  for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
    if (names.has(key) && typeof nested === "string" && nested.trim()) return nested;
  }
  for (const nested of Object.values(value as Record<string, unknown>)) {
    const found = findStringField(nested, names);
    if (found) return found;
  }
  return undefined;
}

function findModelName(value: unknown): string | undefined {
  if (!value || typeof value !== "object") return undefined;
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = findModelName(item);
      if (found) return found;
    }
    return undefined;
  }
  for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
    if (MODEL_FIELD_NAMES.has(key) && typeof nested === "string" && nested.trim()) return nested;
  }
  for (const nested of Object.values(value as Record<string, unknown>)) {
    const found = findModelName(nested);
    if (found) return found;
  }
  return undefined;
}

