const EXTENSION_ID = "llm-router-auto-model";

export default function llmRouterAutoModel(pi: ExtensionAPI): void {
  pi.hooks.addFilter<ModelResolveValue>("model:resolve", EXTENSION_ID, async (value, rawContext) => {
    const context = (rawContext ?? {}) as ModelResolveContext;
    const config = resolveConfig(pi);
    const resolved = await resolveAutoModel(value, context, config);
    const decision = resolved.metadata?.llmRouterDecision as RouterDecision | undefined;
    const unavailable = resolved.metadata?.llmRouterUnavailable as { message?: string } | undefined;
    if (decision) rememberDecision(context.sessionId, decision);
    if (unavailable) rememberUnavailable(context.sessionId, unavailable.message ?? "Auto model unavailable; continuing with the current concrete model.");
    return resolved;
  });

  pi.on("session_start", (_event, ctx) => {
    publishLatestDecision(ctx);
    publishUnavailable(ctx);
  });

  pi.on("turn_start", (_event, ctx) => {
    publishUnavailable(ctx);
  });

  pi.on("model_select", (event, ctx) => {
    clearUnavailable(ctx.sessionManager?.getSessionId?.());
    publishLatestDecision(ctx, event as { model?: { provider?: string; id?: string } });
  });

  pi.on("session_shutdown", (_event, ctx) => {
    clearDecision(ctx.sessionManager?.getSessionId?.());
    if (ctx.hasUI) ctx.ui.setStatus("llm-router", undefined);
  });
}

type LlmRouterUiContext = { hasUI?: boolean; ui?: { setStatus?: (key: string, text: string | undefined) => void; notify?: (message: string, type?: "info" | "warning" | "error" | "success") => void }; sessionManager?: { getSessionId?: () => string } };

function publishLatestDecision(
  ctx: LlmRouterUiContext,
  event?: { model?: { provider?: string; id?: string } },
): void {
  const sessionId = ctx.sessionManager?.getSessionId?.();
  const decision = latestDecision(sessionId);
  if (!ctx.hasUI) return;
  if (!decision) {
    ctx.ui?.setStatus?.("llm-router", undefined);
    return;
  }
  if (event?.model && (event.model.provider !== decision.provider || event.model.id !== decision.modelId)) {
    clearDecision(sessionId);
    ctx.ui?.setStatus?.("llm-router", undefined);
    return;
  }
  ctx.ui?.setStatus?.("llm-router", statusText(decision));
  ctx.ui?.notify?.(notificationText(decision), "info");
}

function publishUnavailable(ctx: LlmRouterUiContext): void {
  const sessionId = ctx.sessionManager?.getSessionId?.();
  const message = latestUnavailable(sessionId);
  if (!ctx.hasUI || !message) return;
  ctx.ui?.setStatus?.("llm-router", "auto:unavailable");
  ctx.ui?.notify?.(message, "warning");
  clearUnavailable(sessionId);
}

export async function resolveAutoModel(
  value: ModelResolveValue,
  context: ModelResolveContext,
  configInput?: RouterConfig | RouterTier,
): Promise<ModelResolveValue> {
  if (context.hasExistingSession) return value;
  const route = normalizeRoute(value.requestedModel);
  if (!route) return value;

  const config = normalizeConfig(configInput);
  const routingMetadata = value.metadata?.routing;
  const classification = await classifyForRouting(routingMetadata, config);
  if (!classification) {
    if (route === "claude-bridge/auto" || route === "openai-codex/auto") {
      return resolveFallbackModel(value, context, config, route);
    }
    const message = "Auto model unavailable: semantic router is not running or returned no decision; continuing with the current concrete model.";
    return {
      ...value,
      metadata: {
        ...(value.metadata ?? {}),
        route,
        reason: ["semantic_router:unavailable"],
        llmRouterUnavailable: {
          route,
          message,
        },
      },
    };
  }
  const providers = allowedProviders(route, value.model?.provider, preferredProvider(context));
  const selected = selectModel(context.modelRegistry, providers, classification.tier, config);
  if (!selected) {
    throw new Error(`Auto model ${route} has no configured models for provider ${providers.join("|")}`);
  }

