import type { Model } from "@valkyriweb/pi-ai";
import { PROVIDER_CANDIDATES } from "./route-graph.ts";
import type { ModelResolveContext, RouterConfig, RouterTier } from "./types.ts";

export function candidateIds(provider: string, tier: RouterTier, config?: RouterConfig): string[] {
  return config?.providers?.[provider as "claude-bridge" | "openai-codex"]?.[tier]
    ?? PROVIDER_CANDIDATES[provider]?.[tier]
    ?? [];
}

export function findModel(
  registry: ModelResolveContext["modelRegistry"],
  provider: string,
  ids: string[],
): Model<any> | undefined {
  for (const id of ids) {
    const found = registry?.find?.(provider, id) ?? findFromList(registry?.getAvailable?.(), provider, id) ?? findFromList(registry?.getAll?.(), provider, id);
    if (found) return found;
  }
  return undefined;
}

export function selectModel(
  registry: ModelResolveContext["modelRegistry"],
  providers: string[],
  tier: RouterTier,
  config?: RouterConfig,
): Model<any> | undefined {
  for (const provider of providers) {
    const model = findModel(registry, provider, candidateIds(provider, tier, config));
    if (model) return model;
  }

  return undefined;
}

function findFromList(models: Model<any>[] | undefined, provider: string, id: string): Model<any> | undefined {
  return models?.find((model) => model.provider === provider && model.id === id);
}

