import json
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

BACKENDS = [(19001, "cheap"), (19002, "medium"), (19003, "frontier")]

class Handler(BaseHTTPRequestHandler):
    model = "unknown"

    def do_GET(self):
        if self.path in ("/health", "/healthz", "/v1/models"):
            body = {"ok": True, "model": self.model}
            if self.path == "/v1/models":
                body = {"object":"list", "data":[{"id": self.model, "object":"model"}]}
            self.send_json(200, body)
            return
        self.send_json(404, {"error": "not found", "model": self.model, "path": self.path})

    def do_POST(self):
        length = int(self.headers.get("content-length") or 0)
        raw = self.rfile.read(length).decode("utf-8", "replace") if length else ""
        try:
            req = json.loads(raw) if raw else {}
        except Exception:
            req = {"raw": raw}
        self.send_json(200, {
            "id": f"echo-{self.model}",
            "object": "chat.completion",
            "model": self.model,
            "choices": [{"index": 0, "message": {"role": "assistant", "content": f"selected:{self.model}"}, "finish_reason": "stop"}],
            "usage": {"prompt_tokens": 1, "completion_tokens": 1, "total_tokens": 2},
            "echo_request_model": req.get("model"),
        })

    def send_json(self, status, body):
        data = json.dumps(body).encode()
        self.send_response(status)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def log_message(self, fmt, *args):
        print(f"{self.model} {self.address_string()} {fmt % args}", flush=True)


def serve(port, model):
    cls = type(f"{model.title()}Handler", (Handler,), {"model": model})
    ThreadingHTTPServer(("0.0.0.0", port), cls).serve_forever()

for port, model in BACKENDS:
    threading.Thread(target=serve, args=(port, model), daemon=True).start()
    print(f"{model} listening on {port}", flush=True)

threading.Event().wait()

