async function withMockSemanticRouter(tier, fn, options = {}) {
  const previousFetch = globalThis.fetch;
  globalThis.fetch = async (_url, _init) => ({
    ok: options.ok ?? true,
    status: options.status ?? 200,
    headers: {
      get(name) {
        const normalized = name.toLowerCase();
        if (normalized === "x-vsr-selected-model" && options.headerModel) return options.headerModel;
        if (normalized === "x-vsr-selected-confidence" && options.headerConfidence !== undefined) return String(options.headerConfidence);
        if (normalized === "x-vsr-selected-decision") return "semantic-provider-route";
        return null;
      },
    },
    async text() {
      if (options.invalidJson) return "not json";
      return JSON.stringify({
        decision_result: { decision_name: "semantic-tier-route" },
        routing_decision: { selected_model: tier, confidence: options.confidence ?? 0.88 },
      });
    },
  });
  try {
    return await fn();
  } finally {
    globalThis.fetch = previousFetch;
  }
}

