import { basename, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import type { ExtensionAPI, ExtensionCommandContext } from "@valkyriweb/pi-coding-agent";
import { isUserTurn } from "@valkyriweb/pi-turn-source";

import { formatGoalSummary } from "./format.js";
import { prepareObjective } from "./objective-dump.js";
import type { GoalStartTurnStrategy } from "./recovery-machine.js";
import {
  compactContinuationPromptStable,
  continuationPromptStable,
} from "./prompts.js";
import { replaceGoal, updateGoalStatus } from "./state.js";
import { CUSTOM_ENTRY_TYPE, type GoalEntrySource, type ThreadGoal } from "./types.js";

export interface CommandHost {
  getGoal(): ThreadGoal | null;
  setGoal(goal: ThreadGoal, source: GoalEntrySource, ctx: GoalCommandContext): void;
  clearGoal(source: GoalEntrySource, ctx: GoalCommandContext): void;
  getGoalStartTurnStrategy(): GoalStartTurnStrategy;
}

const COMMANDS = ["pause", "resume", "clear"] as const;

export type GoalCommandPi = Pick<ExtensionAPI, "registerCommand" | "sendMessage" | "sendUserMessage">;
export type GoalKeywordPi = GoalCommandPi & Pick<ExtensionAPI, "on">;

export interface GoalCommandContext {
  hasUI: boolean;
  ui: Pick<ExtensionCommandContext["ui"], "confirm" | "notify" | "setStatus">;
}

function completions(prefix: string) {
  return COMMANDS.filter((command) => command.startsWith(prefix)).map((command) => ({
    value: command,
    label: command,
    description: `goal ${command}`,
  }));
}

function queueGoalTurn(pi: GoalCommandPi, goal: ThreadGoal, kind: "command_start" | "command_resume"): void {
  pi.sendMessage(
    {
      customType: CUSTOM_ENTRY_TYPE,
      // CACHE CRITICAL: provider-visible goal turns are append-only after
      // dispatch. Use the stable variant so the emitted message itself never
      // needs a later provider-context refresh; live numbers stay behind
      // get_goal.
      content: continuationPromptStable(goal),
      display: false,
      details: { kind, goalId: goal.goalId },
    },
    { triggerTurn: true, deliverAs: "followUp" },
  );
}

function queueGoalUserTurn(pi: GoalCommandPi, goal: ThreadGoal): void {
  // CACHE CRITICAL: stable variant — see queueGoalTurn rationale.
  pi.sendUserMessage(compactContinuationPromptStable(goal), { deliverAs: "followUp" });
}

export async function handleGoalCommand(
  pi: GoalCommandPi,
  host: CommandHost,
  args: string,
  ctx: GoalCommandContext,
): Promise<void> {
  const trimmed = args.trim();
  if (trimmed.length === 0) {
    ctx.ui.notify(formatGoalSummary(host.getGoal()));
    return;
  }

  if (trimmed === "clear") {
    const goal = host.getGoal();
    if (!goal) {
      ctx.ui.notify("No goal is set.", "warning");
      return;
    }
    host.clearGoal("command", ctx);
    ctx.ui.notify("Goal cleared.");
    return;
  }

  if (trimmed === "pause" || trimmed === "resume") {
    const current = host.getGoal();
    if (
      trimmed === "resume" &&
      current?.status === "active" &&
      host.getGoalStartTurnStrategy() === "userFollowUp"
    ) {
      queueGoalUserTurn(pi, current);
      ctx.ui.notify("Goal already active; queued a continuation.");
      return;
    }

    const status = trimmed === "pause" ? "paused" : "active";
    const result = updateGoalStatus(current, status);
    if (!result.ok || !result.goal) {
      ctx.ui.notify(result.message, "warning");
      return;
    }
    host.setGoal(result.goal, "command", ctx);
    ctx.ui.notify(result.message);
    if (trimmed === "resume" && result.goal.status === "active") {
      queueGoalUserTurn(pi, result.goal);
    }
    return;
  }

  const current = host.getGoal();
  if (current && current.status !== "complete") {
    if (!ctx.hasUI) {
      ctx.ui.notify("Clear the existing goal before replacing it.", "error");
      return;
    }
    const shouldReplace = await ctx.ui.confirm(
      "Replace goal?",
      `Current goal:\n${current.objective}\n\nNew goal:\n${trimmed}`,
    );
    if (!shouldReplace) {
      ctx.ui.notify("Goal unchanged.");
      return;
    }
  }

  // Refresh `now` AFTER the confirm await — the user may have sat on the
  // prompt for minutes. Dump filename should reflect when the file actually
  // lands on disk, not when the user typed /goal.
  const now = Date.now();
  const prepared = prepareObjective(trimmed, process.cwd(), now);
  const result = replaceGoal(prepared.objective);
  if (!result.ok || !result.goal) {
    ctx.ui.notify(result.message, "error");
    return;
  }
  if (prepared.objectiveFile) {
    result.goal.objectiveFile = prepared.objectiveFile;
  }
  host.setGoal(result.goal, "command", ctx);
  ctx.ui.notify(
    prepared.objectiveFile
      ? `${result.message} (full objective written to ${prepared.objectiveFile})`
      : result.message,
  );
  if (host.getGoalStartTurnStrategy() === "userFollowUp") {
    queueGoalUserTurn(pi, result.goal);
  } else {
    queueGoalTurn(pi, result.goal, "command_start");
  }
}

// SOURCE OF TRUTH: goal creation/planning contracts live in prompts/*.md,
// shared with the prompt-template path. The active profiles load pi-goal by
// source file (not as a package), so pi never reads this extension's
// `pi.prompts` manifest — the markdown is never discovered as a /command.
// Registering commands here reads the same markdown directly, so the single
// source of truth holds regardless of how the extension is loaded, and the
// commands show up in the TUI palette.
function resolvePromptsDir(): string {
  const sourceDir = dirname(fileURLToPath(import.meta.url));
  const candidates = [
    // Normal source-loaded extension: src/commands.ts -> ../prompts.
    join(sourceDir, "..", "prompts"),
    // Pi's runtime bundle chunks live under src/.pi-bundle-chunks/*.
    join(sourceDir, "..", "..", "prompts"),
  ];
  return candidates.find((candidate) => existsSync(candidate)) ?? candidates[0]!;
}

const PROMPTS_DIR = resolvePromptsDir();
const CREATE_GOAL_PROMPT_PATH = join(PROMPTS_DIR, "create-goal.md");
const PLAN_GOAL_PROMPT_PATH = join(PROMPTS_DIR, "plan-goal.md");

function stripFrontmatter(raw: string): string {
  const match = raw.match(/^---\n[\s\S]*?\n---\n?/);
  return match ? raw.slice(match[0].length) : raw;
}

function expandPromptFromFile(path: string, task: string, cwd = process.cwd(), now = Date.now()): string {
  const body = stripFrontmatter(readFileSync(path, "utf8"));
  const prepared = prepareObjective(task, cwd, now);
  return body.replace(/\$ARGUMENTS\b/g, prepared.objective).replace(/\$@/g, prepared.objective).trimStart();
}

export function expandCreateGoalPrompt(task: string, cwd = process.cwd(), now = Date.now()): string {
  return expandPromptFromFile(CREATE_GOAL_PROMPT_PATH, task, cwd, now);
}

export function expandPlanGoalPrompt(task: string, cwd = process.cwd(), now = Date.now()): string {
  return expandPromptFromFile(PLAN_GOAL_PROMPT_PATH, task, cwd, now);
}

function registerOptimizedGoalCommand(pi: GoalCommandPi, name: string, description: string): void {
  pi.registerCommand(name, {
    description,
    async handler(args: string, _ctx: ExtensionCommandContext) {
      // deliverAs keeps /g usable mid-stream: without it sendUserMessage
      // throws "Agent is already processing" while a turn is running.
      pi.sendUserMessage(expandCreateGoalPrompt(args.trim()), { deliverAs: "steer" });
    },
  });
}

export function registerCreateGoalCommand(pi: GoalCommandPi): void {
