export function sourceOfTruthPreamble(filePath: string): string {
  return `Source-of-truth instructions (read for any detail): ${filePath}`;
}

/**
 * Write the original full objective to docs/goals/goal-<iso>-<hash>.md. Returns the
 * relative file path. Caller stores it on `goal.objectiveFile` and replaces
 * the inline objective with a short pointer.
 */
export function dumpLongGoalObjective(cwd: string, objective: string, now: number): string {
  const dir = path.join(cwd, GOAL_DUMP_DIR);
  fs.mkdirSync(dir, { recursive: true });
  const fileName = `goal-${timestampSlug(now)}-${objectiveHash(objective)}.md`;
  const filePath = path.join(dir, fileName);
  const body = [
    "# Goal Objective",
    "",
    `Generated by pi-goal on ${new Date(now).toISOString()}.`,
    "",
    objective.trim(),
    "",
  ].join("\n");
  fs.writeFileSync(filePath, body, "utf8");
  // Return path relative to cwd for compactness in the inline pointer.
  return path.relative(cwd, filePath);
}

