 * Otherwise dump the full text to a file and return a short pointer suitable
 * for inlining. The pointer fits well within MAX_OBJECTIVE_CHARS and includes
 * the source-of-truth preamble so downstream agents always have a deterministic
 * path to the full text.
 */
export function prepareObjective(objective: string, cwd: string, now: number): PreparedObjective {
  const trimmed = objective.trim();
  if ([...trimmed].length <= INLINE_OBJECTIVE_CHARS) {
    return { objective: trimmed };
