function expandPromptFromFile(path: string, task: string, cwd = process.cwd(), now = Date.now()): string {
  const body = stripFrontmatter(readFileSync(path, "utf8"));
  const prepared = prepareObjective(task, cwd, now);
  return body.replace(/\$ARGUMENTS\b/g, prepared.objective).replace(/\$@/g, prepared.objective).trimStart();
}

export function expandCreateGoalPrompt(task: string, cwd = process.cwd(), now = Date.now()): string {
  return expandPromptFromFile(CREATE_GOAL_PROMPT_PATH, task, cwd, now);
}

export function expandPlanGoalPrompt(task: string, cwd = process.cwd(), now = Date.now()): string {
  return expandPromptFromFile(PLAN_GOAL_PROMPT_PATH, task, cwd, now);
}

function registerOptimizedGoalCommand(pi: GoalCommandPi, name: string, description: string): void {
  pi.registerCommand(name, {
    description,
    async handler(args: string, _ctx: ExtensionCommandContext) {
      // deliverAs keeps /g usable mid-stream: without it sendUserMessage
      // throws "Agent is already processing" while a turn is running.
      pi.sendUserMessage(expandCreateGoalPrompt(args.trim()), { deliverAs: "steer" });
    },
  });
}

