function preferredProvider(context: ModelResolveContext): string | undefined {
  return context.defaultProvider ?? context.settingsManager?.getDefaultProvider?.();
}

async function classifyForRouting(metadata: RoutingMetadata | undefined, config: RouterConfig): Promise<Classification | undefined> {
  const floor = tierFloorForMetadata(metadata);
  if (config.tier) return applyTierFloor({ tier: config.tier, reason: ["config:tier"], confidence: 1 }, floor);
  const classification = config.classifier === "local-qwen"
    ? await classifyWithLocalQwen(metadata, config)
    : await classifyWithSemanticRouter(metadata, config);
  return applyTierFloor(classification, floor);
}

const TIER_RANK: Record<RouterTier, number> = {
  cheap: 0,
  medium: 1,
  frontier: 2,
};

const HIGH_RISK_GOAL_RE = /\b(kubernetes|k8s|flux|gitops|etcd|control-plane|longhorn|cluster|production|prod-critical|rollback|restore|snapshot|ha\b|quorum|taint|toleration|pdb|eviction|security|secrets?|auth|migration|data-loss|destructive|server-side dry-run|live state|failure domain|arc|github runners?|buildkit)\b/i;

function applyTierFloor(classification: Classification | undefined, floor: RouterTier | undefined): Classification | undefined {
  if (!classification || !floor) return classification;
  if (TIER_RANK[classification.tier] >= TIER_RANK[floor]) return classification;
  return {
    ...classification,
    tier: floor,
    selectedProvider: undefined,
    selectedModelId: undefined,
    selectedLabel: undefined,
    reason: [...classification.reason, `tier_floor:${floor}`],
  };
}

function tierFloorForMetadata(metadata: RoutingMetadata | undefined): RouterTier | undefined {
  const prompt = metadata?.promptPreview ?? "";
  if (!prompt.includes("<pi_goal_continuation")) return undefined;
  return HIGH_RISK_GOAL_RE.test(prompt) ? "frontier" : "medium";
}

