test("/goal objective externalizes oversized text before queuing a start turn", async () => {
  const cwd = mkdtempSync(join(tmpdir(), "pi-goal-command-"));
  const originalCwd = process.cwd();
  process.chdir(cwd);
  try {
    const harness = createHarness();
    const largeObjective = `Ship the session restore flow.\n${"large pasted context\n".repeat(350)}`;

    await handleGoalCommand(harness.pi, harness.host, largeObjective, harness.ctx);

    assert.ok(harness.goal?.objectiveFile);
    assert.match(harness.goal.routingPreview ?? "", /Ship the session restore flow/);
    assert.match(harness.goal.routingPreview ?? "", /large pasted context/);
    assert.match(harness.goal.objective, /Source-of-truth instructions \(read for any detail\): docs\/goals\/goal-/);
    assert.doesNotMatch(harness.goal.objective, /large pasted context\nlarge pasted context/);
    assert.match(harness.notifications.at(-1) ?? "", /full objective written to docs\/goals\/goal-/);

    const dumped = readFileSync(join(cwd, harness.goal.objectiveFile), "utf8");
    assert.match(dumped, /Ship the session restore flow/);
    assert.match(dumped, /large pasted context/);

    const queued = harness.sentMessages[0]?.message.content;
    assert.equal(typeof queued, "string");
    assert.match(String(queued), /<untrusted_routing_preview>/);
    assert.match(String(queued), /Ship the session restore flow/);
    assert.ok(String(queued).length < largeObjective.length, "queued goal turn keeps only a bounded routing preview");
  } finally {
    process.chdir(originalCwd);
    rmSync(cwd, { recursive: true, force: true });
  }
});

